function () {
  // Lee la elección que guarda el banner de cookies de la web.
  // Devuelve true solo si la persona aceptó las cookies de marketing.
  try {
    var guardado = JSON.parse(window.localStorage.getItem('cookie-consent'));
    return !!(guardado && guardado.categories && guardado.categories.marketing === true);
  } catch (e) {
    return false;
  }
}

function () {
  // «blog» si la página es /blog o cuelga de /blog; si no, «web».
  // En page_view y section_view usa la ruta que manda la web; en el resto, la de la página actual.
  var ruta = {{dlv.page_path}} || {{Page Path}} || '';
  return /^\/blog(\/|\?|#|$)/.test(ruta) ? 'blog' : 'web';
}

function () {
  // El enlace del clic sin lo que va detrás de «?» (los UTM), para Google Analytics.
  var url = {{dlv.link_url}};
  if (!url) {
    return undefined;
  }
  return String(url).split('?')[0];
}
